const authzUpdatePolicy = `-- name: AuthzUpdatePolicy :many
UPDATE authz_policy
   SET description = $1::text, resource_type = $2::text,
       version = version + 1, updated_at = now(), updated_by = NULLIF($3::text, '')::uuid
 WHERE name = $4::text
   AND ($5::bigint < 0 OR version = $5::bigint)
RETURNING id::text AS id, version
`

type AuthzUpdatePolicyParams struct {
	Description  string
	ResourceType string
	Actor        string
	Name         string
	Expected     int64
}

type AuthzUpdatePolicyRow struct {
	ID      string
	Version int64
}

// The update that carries the optimistic check: a negative expected version is the
// deliberate blind write (If-Match: *); a version that does not match returns no row.
func (q *Queries) AuthzUpdatePolicy(ctx context.Context, arg AuthzUpdatePolicyParams) ([]AuthzUpdatePolicyRow, error) {
	rows, err := q.db.Query(ctx, authzUpdatePolicy,
		arg.Description,
		arg.ResourceType,
		arg.Actor,
		arg.Name,
		arg.Expected,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuthzUpdatePolicyRow{}
	for rows.Next() {
		var i AuthzUpdatePolicyRow
		if err := rows.Scan(&i.ID, &i.Version); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
